(() => {
  const announce = (() => {
    let el, timer;
    return (msg) => {
      if (!el) {
        el = document.createElement("div");
        el.className = "toast";
        el.setAttribute("role", "status");
        el.setAttribute("aria-live", "polite");
        document.body.append(el);
      }
      el.textContent = msg;
      el.classList.add("show");
      clearTimeout(timer);
      timer = setTimeout(() => el.classList.remove("show"), 1900);
    };
  })();

  const copyText = async (text, fallbackEl) => {
    try {
      await navigator.clipboard.writeText(text);
      announce("Copied to clipboard");
    } catch (e) {
      if (fallbackEl) {
        const r = document.createRange();
        r.selectNodeContents(fallbackEl);
        const s = getSelection();
        s.removeAllRanges();
        s.addRange(r);
      }
      announce("Text selected. Press Ctrl+C or Cmd+C to copy.");
    }
  };
  document.addEventListener("click", (ev) => {
    const btn = ev.target.closest("[data-copy]");
    if (!btn) return;
    const target = document.getElementById(btn.dataset.copy);
    if (!target) return;
    copyText(target.textContent.trim(), target.hidden ? null : target);
  });


  document.addEventListener("click", (ev) => {
    const tab = ev.target.closest(".cite-tab");
    if (!tab) return;
    const list = tab.parentElement;
    const box = list.parentElement;
    list.querySelectorAll(".cite-tab").forEach((t) => { const on = t === tab; t.setAttribute("aria-selected", String(on)); t.tabIndex = on ? 0 : -1; });
    box.querySelectorAll(".cite-panel").forEach((p) => { p.hidden = p.id !== tab.getAttribute("aria-controls"); });
  });
  document.addEventListener("keydown", (ev) => {
    const tab = ev.target.closest && ev.target.closest(".cite-tab");
    if (!tab || !["ArrowLeft", "ArrowRight", "Home", "End"].includes(ev.key)) return;
    const tabs = [...tab.parentElement.querySelectorAll(".cite-tab")];
    let i = tabs.indexOf(tab);
    i = ev.key === "Home" ? 0 : ev.key === "End" ? tabs.length - 1 : (i + (ev.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length;
    ev.preventDefault();
    tabs[i].focus();
    tabs[i].click();
  });

  document.querySelectorAll("[data-print]").forEach((b) => {
    if (window.self !== window.top) { b.hidden = true; return; }
    b.addEventListener("click", () => window.print());
  });

  const sheet = document.getElementById("site-menu");
  if (sheet) {
    sheet.addEventListener("toggle", (e) => {
      document.documentElement.style.overflow = e.newState === "open" ? "hidden" : "";
      document.querySelectorAll("[popovertarget='site-menu']").forEach((b) => b.setAttribute("aria-expanded", String(e.newState === "open")));
    });
    sheet.addEventListener("click", (e) => { if (e.target.closest("a") && sheet.hidePopover) sheet.hidePopover(); });
  }


  const header = document.querySelector(".site-header");
  if (header) {
    const onS = () => header.classList.toggle("scrolled", scrollY > 24);
    addEventListener("scroll", onS, { passive: true });
    onS();
  }


  const totop = document.querySelector("[data-totop]");
  if (totop) {
    let ticking = false, shown = false;
    const red = matchMedia("(prefers-reduced-motion: reduce)");
    const upd = () => {
      ticking = false;
      const max = document.documentElement.scrollHeight - innerHeight;
      const y = scrollY;
      totop.style.setProperty("--sp", max > 0 ? Math.min(1, y / max).toFixed(4) : 0);
      const on = y > Math.max(480, innerHeight * 0.7);
      if (on !== shown) {
        shown = on;
        totop.classList.toggle("show", on);
        totop.setAttribute("aria-hidden", String(!on));
        totop.tabIndex = on ? 0 : -1;
      }
    };
    addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(upd); } }, { passive: true });
    addEventListener("resize", upd);
    totop.addEventListener("click", () => {
      scrollTo({ top: 0, behavior: red.matches ? "auto" : "smooth" });
      const target = document.querySelector(".brand");
      const done = () => { if (target) target.focus({ preventScroll: true }); };
      if (red.matches || !("onscrollend" in window)) setTimeout(done, red.matches ? 0 : 700);
      else addEventListener("scrollend", done, { once: true });
    });
    upd();
  }

  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

  document.querySelectorAll("[data-words]").forEach((el) => {
    const walk = (node) => {
      [...node.childNodes].forEach((n) => {
        if (n.nodeType === 3) {
          const frag = document.createDocumentFragment();
          n.textContent.split(/(\s+)/).forEach((part) => {
            if (!part) return;
            if (/^\s+$/.test(part)) { frag.append(part); return; }
            const s = document.createElement("span");
            s.className = "w";
            s.textContent = part;
            frag.append(s);
          });
          n.replaceWith(frag);
        } else if (n.nodeType === 1) walk(n);
      });
    };
    walk(el);
    const ws = [...el.querySelectorAll(".w")];
    if (reduce) { ws.forEach((w) => w.classList.add("on")); return; }
    let ticking = false;
    const upd = () => {
      ticking = false;
      const r = el.getBoundingClientRect();
      const vh = innerHeight;
      const p = Math.min(1, Math.max(0, (vh * 0.85 - r.top) / (r.height + vh * 0.35)));
      const n = Math.round(p * ws.length);
      ws.forEach((w, i) => w.classList.toggle("on", i < n));
    };
    addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(upd); } }, { passive: true });
    addEventListener("resize", upd);
    upd();
  });

  document.querySelectorAll("[data-lib]").forEach((lib) => {
    const track = lib.querySelector("[data-lib-track]");
    const bar = lib.querySelector("[data-lib-bar]");
    const num = lib.querySelector("[data-lib-n]");
    const vols = [...track.children];
    const mq = matchMedia("(min-width: 64rem) and (hover: hover)");
    let pinned = false, dist = 0, ticking = false;
    const setNum = (p) => {
      const k = Math.min(vols.length, Math.max(1, Math.round(p * (vols.length - 1)) + 1));
      if (num) num.textContent = String(k).padStart(2, "0");
      if (bar) bar.style.setProperty("--pr", Math.max(0.04, p).toFixed(4));
    };
    const layout = () => {
      pinned = mq.matches && !reduce;
      lib.classList.toggle("pinned", pinned);
      track.style.transform = "";
      if (pinned) {
        const last = vols[vols.length - 1];
        const pad = parseFloat(getComputedStyle(track).paddingLeft) || 0;
        dist = Math.max(0, last.offsetLeft + last.offsetWidth + pad - innerWidth);
        lib.style.height = `calc(100svh + ${dist}px)`;
      } else {
        lib.style.height = "";
      }
      upd();
    };
    const upd = () => {
      ticking = false;
      if (pinned) {
        const r = lib.getBoundingClientRect();
        const p = Math.min(1, Math.max(0, -r.top / Math.max(1, dist)));
        track.style.transform = `translate3d(${-p * dist}px,0,0)`;
        setNum(p);
      } else {
        const max = track.scrollWidth - track.clientWidth;
        setNum(max > 0 ? track.scrollLeft / max : 0);
      }
    };
    addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(upd); } }, { passive: true });
    track.addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(upd); } }, { passive: true });
    addEventListener("resize", layout);
    mq.addEventListener("change", layout);
    addEventListener("load", layout);
    layout();
  });

  const counters = document.querySelectorAll("[data-count]");
  if (counters.length && "IntersectionObserver" in window && !reduce) {
    const fmt = (n) => n.toLocaleString("en-GB");
    const io = new IntersectionObserver((entries) => entries.forEach((en) => {
      if (!en.isIntersecting) return;
      io.unobserve(en.target);
      const el = en.target, end = +el.dataset.count, suf = el.dataset.suffix || "", t0 = performance.now(), dur = 1600;
      const step = (t) => {
        const k = Math.min(1, (t - t0) / dur);
        const v = Math.round(end * (1 - Math.pow(1 - k, 4)));
        el.textContent = fmt(v) + suf;
        if (k < 1) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    }), { threshold: 0.6 });
    counters.forEach((c) => io.observe(c));
  }

  document.querySelectorAll("[data-rail]").forEach((rail) => {
    const sc = rail.querySelector(".rail-scroll");
    const prev = rail.querySelector("[data-rail-prev]");
    const next = rail.querySelector("[data-rail-next]");
    if (!sc) return;
    const step = () => Math.max(sc.clientWidth * 0.8, 200);
    const sync = () => {
      if (prev) prev.disabled = sc.scrollLeft < 8;
      if (next) next.disabled = sc.scrollLeft + sc.clientWidth > sc.scrollWidth - 8;
    };
    if (prev) prev.addEventListener("click", () => sc.scrollBy({ left: -step(), behavior: "smooth" }));
    if (next) next.addEventListener("click", () => sc.scrollBy({ left: step(), behavior: "smooth" }));
    sc.addEventListener("scroll", sync, { passive: true });
    sync();
  });

  document.querySelectorAll("[data-filter]").forEach((scope) => {
    const items = [...scope.querySelectorAll("[data-item]")];
    const sections = [...scope.querySelectorAll("[data-section]")];
    const input = scope.querySelector("[data-filter-search]");
    const countEl = scope.querySelector("[data-filter-count]");
    const empty = scope.querySelector("[data-filter-empty]");
    const reset = scope.querySelector("[data-filter-reset]");
    const state = {};
    const norm = (s) => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
    const apply = () => {
      const terms = norm(input ? input.value : "").split(/\s+/).filter(Boolean);
      let n = 0;
      items.forEach((it) => {
        const hay = it.dataset.text || "";
        const tags = (it.dataset.tags || "").split(" ");
        const ok = terms.every((t) => hay.includes(t)) && Object.values(state).every((v) => v === "all" || tags.includes(v));
        it.hidden = !ok;
        if (ok) n++;
      });
      sections.forEach((s) => { s.hidden = !s.querySelector("[data-item]:not([hidden])"); });
      if (countEl) countEl.textContent = n === items.length ? `Showing all ${n}` : `Showing ${n} of ${items.length}`;
      if (empty) empty.hidden = n !== 0;
      if (reset) reset.hidden = !(terms.length || Object.values(state).some((v) => v !== "all"));
    };
    scope.querySelectorAll("[data-group]").forEach((g) => {
      const key = g.dataset.group;
      state[key] = "all";
      g.querySelectorAll("[data-value]").forEach((b) => b.addEventListener("click", () => {
        state[key] = b.dataset.value;
        g.querySelectorAll("[data-value]").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
        apply();
      }));
    });
    if (input) input.addEventListener("input", apply);
    if (reset) reset.addEventListener("click", () => {
      if (input) input.value = "";
      scope.querySelectorAll("[data-group]").forEach((g) => {
        state[g.dataset.group] = "all";
        g.querySelectorAll("[data-value]").forEach((x) => x.setAttribute("aria-pressed", String(x.dataset.value === "all")));
      });
      apply();
    });
    const pre = location.hash.slice(1);
    const preBtn = pre && scope.querySelector(`[data-value="${CSS.escape(pre)}"]`);
    if (preBtn) preBtn.click(); else apply();
  });

  const dlg = document.getElementById("palette");
  if (dlg && typeof IDX !== "undefined") {
    const input = dlg.querySelector("input");
    const res = dlg.querySelector(".pal-res");
    let links = [], active = 0;
    const norm = (s) => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
    const esc = (s) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
    const mark = () => {
      links.forEach((a, i) => a.setAttribute("aria-selected", String(i === active)));
      if (links[active]) { input.setAttribute("aria-activedescendant", links[active].id); links[active].scrollIntoView({ block: "nearest" }); }
      else input.removeAttribute("aria-activedescendant");
    };
    const render = () => {
      const terms = norm(input.value).split(/\s+/).filter(Boolean);
      const hits = terms.length ? IDX.filter((it) => { const h = norm(it.t + " " + it.s + " " + it.k + " " + it.g); return terms.every((t) => h.includes(t)); }) : IDX.filter((it) => it.g === "Pages");
      const groups = {};
      hits.forEach((h) => { (groups[h.g] = groups[h.g] || []).push(h); });
      let html = "", i = 0;
      Object.entries(groups).forEach(([g, list]) => {
        html += `<div class="pal-group" role="presentation">${esc(g)}</div>`;
        list.slice(0, 8).forEach((h) => { html += `<a href="${esc(h.u)}" role="option" id="pal-${i++}" aria-selected="false">${esc(h.t)}<small>${esc(h.s)}</small></a>`; });
      });
      res.innerHTML = html || `<p class="pal-empty">Nothing matches “${esc(input.value)}”. Try a book title, a journal, a city or a research theme.</p>`;
      links = [...res.querySelectorAll("a")];
      active = 0;
      mark();
    };
    const open = () => { if (dlg.open) return; if (sheet && sheet.matches(":popover-open")) sheet.hidePopover(); dlg.showModal(); input.value = ""; render(); input.focus(); };
    input.addEventListener("input", render);
    input.addEventListener("keydown", (e) => {
      if (e.key === "ArrowDown") { e.preventDefault(); active = Math.min(links.length - 1, active + 1); mark(); }
      else if (e.key === "ArrowUp") { e.preventDefault(); active = Math.max(0, active - 1); mark(); }
      else if (e.key === "Enter" && links[active]) { e.preventDefault(); links[active].click(); dlg.close(); }
    });
    res.addEventListener("click", (e) => { if (e.target.closest("a")) dlg.close(); });
    dlg.addEventListener("click", (e) => { if (e.target === dlg) dlg.close(); });
    dlg.querySelectorAll("[data-palette-close]").forEach((b) => b.addEventListener("click", () => dlg.close()));
    document.querySelectorAll("[data-palette-open]").forEach((b) => b.addEventListener("click", open));
    document.addEventListener("keydown", (e) => {
      const typing = /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName) || document.activeElement.isContentEditable;
      if ((e.key === "k" || e.key === "K") && (e.metaKey || e.ctrlKey)) { e.preventDefault(); open(); }
      else if (e.key === "/" && !typing) { e.preventDefault(); open(); }
    });
    const isMac = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
    document.querySelectorAll("[data-kbd]").forEach((k) => { k.textContent = isMac ? "⌘K" : "Ctrl K"; });
  }
})();
